import React, { useEffect, useState, useRef } from 'react';
import { fetchReviews } from '../api/reviewApi';
import ReviewCard from '../components/ReviewCard';
import axios from '../api/axiosConfig';

function Magazine() {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeCategory, setActiveCategory] = useState('전체');
  const [hoveredReviewer, setHoveredReviewer] = useState(null);

  // 인기 리뷰어 데이터
  const topReviewers = [
    {
      id: 1,
      name: '뷰티민지',
      username: '@beauty_minji',
      avatar: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&h=200&fit=crop&crop=face',
      followers: '12.3만',
      reviews: 234,
      specialty: '스킨케어',
      verified: true,
      bio: '피부과 전문의 출신 뷰티 크리에이터 💫',
      recentReview: '라네즈 워터뱅크 크림 솔직 리뷰',
      gradient: 'linear-gradient(135deg, #ff9a9e 0%, #fecfef 100%)'
    },
    {
      id: 2,
      name: '스킨케어수아',
      username: '@skincare_sua',
      avatar: 'https://images.unsplash.com/photo-1529626455594-4ff0802cfb7e?w=200&h=200&fit=crop&crop=face',
      followers: '8.7만',
      reviews: 189,
      specialty: '민감성 피부',
      verified: true,
      bio: '민감성 피부 전문 리뷰어 🌸',
      recentReview: '무자극 클렌징 폼 TOP 5',
      gradient: 'linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%)'
    },
    {
      id: 3,
      name: '인플루언서 채희',
      username: '@chaehee_beauty',
      avatar: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&h=200&fit=crop&crop=face',
      followers: '25.1만',
      reviews: 312,
      specialty: '퍼퓸 & 프래그런스',
      verified: true,
      bio: '트렌디한 메이크업 & 뷰티 인플루언서 ✨',
      recentReview: '롬앤 신상 틴트 전색상 비교',
      gradient: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
    }
  ];

  // 카테고리 목록
  const categories = ['전체', '스킨케어', '메이크업', '헤어케어', '바디케어', '향수'];

  // 트렌딩 태그
  const trendingTags = [
    { tag: '#글로우피부', count: '2.3만' },
    { tag: '#수분크림추천', count: '1.8만' },
    { tag: '#데일리메이크업', count: '1.5만' },
    { tag: '#민감피부', count: '1.2만' },
    { tag: '#비건뷰티', count: '9.8천' },
  ];

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        const reviewsRes = await fetchReviews({ page: 1, limit: 8 });
        const texts = reviewsRes.data.map(r => r.text);
        const resp = await axios.post('/ai/summarize', { texts });
        setSummary(resp.data.summary);
      } catch (err) {
        console.error('magazine load failed', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  return (
    <div 
      style={{ 
        padding: '40px 20px', 
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #fff 0%, #fff5f7 50%, #faf5ff 100%)',
        position: 'relative'
      }}
    >
      {/* 헤더 */}
      <div style={{ textAlign: 'center', marginBottom: 50, maxWidth: 800, margin: '0 auto 50px' }}>
        <h1 style={{ 
          fontSize: 42, 
          fontWeight: 900, 
          background: 'linear-gradient(135deg, #ff6b9d 0%, #c44cff 50%, #6366f1 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          marginBottom: 16
        }}>
          🔍 탐색
        </h1>
        <p style={{ color: '#666', fontSize: 16, lineHeight: 1.6 }}>
          인기 리뷰어들의 생생한 뷰티 리뷰를 만나보세요
        </p>
      </div>

      {/* 카테고리 탭 */}
      <div style={{ 
        display: 'flex', 
        gap: 12, 
        justifyContent: 'center', 
        marginBottom: 40,
        flexWrap: 'wrap'
      }}>
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            style={{
              padding: '10px 24px',
              borderRadius: 25,
              border: 'none',
              background: activeCategory === cat 
                ? 'linear-gradient(135deg, #ff6b9d, #c44cff)' 
                : 'white',
              color: activeCategory === cat ? 'white' : '#666',
              fontWeight: 600,
              fontSize: 14,
              cursor: 'pointer',
              boxShadow: activeCategory === cat 
                ? '0 4px 15px rgba(255,107,157,0.4)' 
                : '0 2px 8px rgba(0,0,0,0.08)',
              transition: 'all 0.3s ease',
              transform: activeCategory === cat ? 'scale(1.05)' : 'scale(1)'
            }}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* 급상승 리뷰어 섹션 */}
      <div style={{ maxWidth: 1200, margin: '0 auto 60px' }}>
        <div style={{ 
          display: 'flex', 
          alignItems: 'center', 
          gap: 12,
          marginBottom: 24 
        }}>
          <span style={{ fontSize: 28 }}>🚀</span>
          <div>
            <h2 style={{ 
              fontSize: 24, 
              fontWeight: 800, 
              color: '#1a1a2e',
              margin: 0
            }}>
              급상승 리뷰어
            </h2>
            <p style={{ margin: 0, color: '#888', fontSize: 14 }}>이번 주 주목할 크리에이터</p>
          </div>
        </div>

        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(3, 1fr)', 
          gap: 20 
        }}>
          {topReviewers.map((reviewer, idx) => (
            <div
              key={reviewer.id}
              onMouseEnter={() => setHoveredReviewer(reviewer.id)}
              onMouseLeave={() => setHoveredReviewer(null)}
              style={{
                background: '#fffef5',
                borderRadius: 20,
                padding: '28px 24px',
                textAlign: 'center',
                boxShadow: hoveredReviewer === reviewer.id 
                  ? '0 12px 40px rgba(0,0,0,0.12)' 
                  : '0 4px 20px rgba(0,0,0,0.06)',
                transition: 'all 0.3s ease',
                transform: hoveredReviewer === reviewer.id ? 'translateY(-4px)' : 'translateY(0)',
                cursor: 'pointer',
                position: 'relative'
              }}
            >
              {/* 1위 뱃지 */}
              {idx === 0 && (
                <div style={{
                  position: 'absolute',
                  top: 16,
                  right: 16,
                  background: 'linear-gradient(135deg, #ff6b9d, #ff8a65)',
                  color: 'white',
                  padding: '6px 12px',
                  borderRadius: 20,
                  fontSize: 12,
                  fontWeight: 800,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 4
                }}>
                  <span>🏆</span> 1위
                </div>
              )}

              {/* 프로필 이미지 + 이름 라벨 */}
              <div style={{ 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center',
                gap: 8,
                marginBottom: 20
              }}>
                <div style={{
                  background: '#e8f5e9',
                  borderRadius: 20,
                  padding: '6px 14px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 6
                }}>
                  <span style={{ fontSize: 14 }}>🌿</span>
                  <span style={{ fontSize: 13, fontWeight: 600, color: '#2e7d32' }}>{reviewer.name}</span>
                </div>
              </div>

              {/* 프로필 이미지 */}
              <div style={{
                width: 90,
                height: 90,
                borderRadius: '50%',
                overflow: 'hidden',
                margin: '0 auto 16px',
                border: '3px solid #fff',
                boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
              }}>
                <img 
                  src={reviewer.avatar} 
                  alt={reviewer.name}
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover'
                  }}
                  onError={(e) => {
                    e.target.src = `https://ui-avatars.com/api/?name=${encodeURIComponent(reviewer.name)}&background=ff6b9d&color=fff&size=200`;
                  }}
                />
              </div>

              {/* 이름 */}
              <h3 style={{ 
                fontSize: 18, 
                fontWeight: 800, 
                color: '#1a1a2e',
                marginBottom: 6
              }}>
                {reviewer.name}
              </h3>

              {/* 전문 분야 */}
              <p style={{ 
                color: '#888', 
                fontSize: 13, 
                marginBottom: 16 
              }}>
                {reviewer.specialty} 전문
              </p>

              {/* 팔로워 증가 */}
              <div style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 6,
                background: 'linear-gradient(135deg, #e8f5e9, #c8e6c9)',
                padding: '8px 16px',
                borderRadius: 20,
                marginBottom: 16
              }}>
                <span style={{ color: '#2e7d32', fontWeight: 700, fontSize: 14 }}>팔로워</span>
                <span style={{ color: '#43a047', fontWeight: 800, fontSize: 15 }}>+{reviewer.followerGain || (idx === 0 ? '324' : idx === 1 ? '287' : '198')}</span>
              </div>

              {/* 한 마디 */}
              <p style={{ 
                color: '#666', 
                fontSize: 13, 
                fontStyle: 'italic',
                lineHeight: 1.5,
                padding: '0 10px'
              }}>
                "{reviewer.quote || (idx === 0 ? '진정성 있는 리뷰가 제 원칙이에요' : idx === 1 ? '민감한 피부를 위한 꿀팁 공유해요' : '데일리룩 추천은 저에게 맡겨주세요')}"
              </p>
            </div>
          ))}
        </div>
      </div>

      {/* 트렌딩 태그 */}
      <div style={{ maxWidth: 1200, margin: '0 auto 60px' }}>
        <h2 style={{ 
          fontSize: 24, 
          fontWeight: 800, 
          color: '#1a1a2e',
          marginBottom: 24,
          display: 'flex',
          alignItems: 'center',
          gap: 10
        }}>
          <span>🔥</span> 트렌딩 태그
        </h2>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
          {trendingTags.map((item, idx) => (
            <div
              key={idx}
              style={{
                background: 'white',
                borderRadius: 16,
                padding: '14px 20px',
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                boxShadow: '0 4px 15px rgba(0,0,0,0.06)',
                cursor: 'pointer',
                transition: 'all 0.3s ease'
              }}
              onMouseOver={e => {
                e.currentTarget.style.transform = 'translateY(-3px)';
                e.currentTarget.style.boxShadow = '0 8px 25px rgba(255,107,157,0.15)';
              }}
              onMouseOut={e => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = '0 4px 15px rgba(0,0,0,0.06)';
              }}
            >
              <span style={{ 
                fontWeight: 700, 
                fontSize: 15,
                background: 'linear-gradient(135deg, #ff6b9d, #c44cff)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent'
              }}>
                {item.tag}
              </span>
              <span style={{ 
                fontSize: 12, 
                color: '#888',
                background: '#f0f0f0',
                padding: '4px 10px',
                borderRadius: 10
              }}>
                {item.count}
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* AI 리뷰 요약 섹션 */}
      <div style={{ maxWidth: 1200, margin: '0 auto' }}>
        <h2 style={{ 
          fontSize: 24, 
          fontWeight: 800, 
          color: '#1a1a2e',
          marginBottom: 24,
          display: 'flex',
          alignItems: 'center',
          gap: 10
        }}>
          <span>🤖</span> AI 리뷰 매거진
        </h2>
        <p style={{ color: '#666', marginBottom: 20 }}>AI가 여러 리뷰를 분석해 트렌드와 핵심을 정리해드립니다.</p>

        {loading && (
          <div style={{ 
            padding: 40, 
            textAlign: 'center', 
            background: 'white', 
            borderRadius: 16,
            boxShadow: '0 4px 15px rgba(0,0,0,0.06)'
          }}>
            <div style={{ fontSize: 40, marginBottom: 16 }}>✨</div>
            <p style={{ color: '#888' }}>AI가 리뷰를 분석 중입니다...</p>
          </div>
        )}

        {summary && (
          <div style={{ 
            padding: 24, 
            background: 'white', 
            borderRadius: 20, 
            boxShadow: '0 8px 30px rgba(0,0,0,0.08)',
            border: '1px solid rgba(255,107,157,0.1)'
          }}>
            <div dangerouslySetInnerHTML={{ __html: summary.replace(/\n/g, '<br/>') }} />
          </div>
        )}
      </div>

      {/* 스타일 */}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}

export default Magazine;
